solution:
function isBalanced(text) {
  const partner = { ')': '(', ']': '[', '}': '{' };
  const open = [];
  for (const ch of text) {
    if (ch === '(' || ch === '[' || ch === '{') {
      open.push(ch);
    } else if (ch in partner) {
      if (open.length === 0) return false;
      if (open.pop() !== partner[ch]) return false;
    }
  }
  return open.length === 0;
}

tests.code:
assertEqual(isBalanced(']'), false);
assertEqual(isBalanced(')('), false);
assertEqual(isBalanced('())'), false);
